        "localizador": "L05"
      }
    ],
    "lacunas": [
      "O término novo não pode ser calculado sem as precedências e os requisitos de disponibilidade; portanto, não se determina se haverá incidência de extensão além de D10."
    ],
    "motivo": "A troca não tem cobrança adicional, mas o custo total pode depender da extensão, que depende do término não determinável.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
